examples.code:
service OrderService {
  entity Orders as projection on db.Orders actions {
    action approve(comment: String) returns Orders;   // bound action (POST)
  };
  function getTotalRevenue() returns Decimal;         // unbound function (GET)
}

type Address {
  street     : String(60);
  city       : String(40);
  postalCode : String(10);
}

entity Customers {
  key ID          : UUID;
  billingAddress  : Address;   // reused
  shippingAddress : Address;
}
// binding: <Text text="{billingAddress/city}" /> (V4 path with the structured property)

entity Products as projection on db.Products {
  @Common.Label: 'Product Name'
  name,

  @Common.Text: category.name
  @Common.ValueList: { entity: 'Categories' }
  category
};

annotate Products with @(
  Capabilities.DeleteRestrictions: { Deletable: false }   // was sap:deletable="false"
);
